import json

PROJECT_MAP = "/tmp/oxygen-work-VJrpF9/user-simulation-20260831-01a0597b-review/project-map.json"

scope = {
    "evaluation_program_scope",
    "evaluation_protocol_provenance",
    "simulatorarena_protocol_provenance",
    "soul_dataset_provenance",
}
foundation = {
    "evaluation_runner_foundation",
    "local_soul_evaluator_runtime",
    "local_evaluation_pipeline",
    "evaluation_model_role_routing",
    "fixed_auxiliary_model_reruns",
    "provider_access_and_reliability",
}
method = {
    "comparative_audit_methodology",
    "comparative_judge_experiment",
    "humanual_comparative_judging",
    "evaluation_score_calibration",
    "simarena_prompt_protocol_audit",
}
audit = {
    "direct_profile_leakage_audit",
    "user_specificity_audit",
    "profile_direct_audit_design",
    "audit_metrics_and_validation",
}
execution = {
    "slurm_evaluation_orchestration",
    "slurm_cpu_partition_skill",
    "approval_gate_reviews",
    "approval_risk_assessments",
}
analysis = {
    "evaluation_analysis_pipeline",
    "reusable_evaluation_analysis",
    "reusable_metrics_reporting",
    "model_performance_findings",
    "model_performance_diagnostics",
}
reporting = {
    "evaluation_reporting",
    "evaluation_reporting_visuals",
    "evaluation_report_visualizations",
    "evaluation_presentation_deck",
    "evaluation_visualization",
}
owner_by_suffix = {
    **{key: "chapter-questions-and-provenance" for key in scope},
    **{key: "chapter-evaluator-foundation" for key in foundation},
    **{key: "chapter-comparative-method" for key in method},
    **{key: "chapter-user-specificity-audit" for key in audit},
    **{key: "chapter-orchestrated-execution" for key in execution},
    **{key: "chapter-findings-and-analysis" for key in analysis},
    **{key: "chapter-reporting-and-visualization" for key in reporting},
}

with open(PROJECT_MAP, encoding="utf-8") as handle:
    units = json.load(handle)["semantic_manifest"]["units"]

rows = []
for unit in units:
    suffix = unit["id"].split("__", 1)[1]
    if unit["kind"] == "routine":
        rows.append({
            "unitId": unit["id"],
            "disposition": "excluded",
            "exclusionReason": "routine_non_narrative",
        })
    elif unit["kind"] in {
        "operational_metadata",
        "viewer_setup",
        "local_viewer_operations",
        "organization_workflow",
    }:
        rows.append({
            "unitId": unit["id"],
            "disposition": "excluded",
            "exclusionReason": "outside_story_scope",
        })
    else:
        owner = owner_by_suffix.get(suffix)
        if owner is None:
            raise SystemExit(f"unclassified semantic unit: {unit['id']} ({unit['kind']})")
        rows.append({
            "unitId": unit["id"],
            "disposition": "represented",
            "ownerId": owner,
        })

if len(rows) != len(units) or len({row["unitId"] for row in rows}) != len(units):
    raise SystemExit("coverage draft does not cover the semantic universe exactly once")

print(json.dumps({"rows": rows}, indent=2, ensure_ascii=False))

