    "ownerId": "chapter-orchestrated-execution",
    "kind": "direction_change",
    "title": "From One Evaluation Run to Resilient Orchestration",
    "overview": "A locally validated evaluation grew into a reusable Slurm program that coordinated model and judge waves across constrained CPU partitions. Smoke tests, resumable outputs, dependency control, duplicate prevention, and evidence-based recovery kept failures bounded while the evaluation expanded.",
    "transition": {
      "before": "The evaluation began as one 800-episode run whose execution depended on a single scheduler path and ad hoc queue handling.",
      "after": "It became a reusable, validated orchestration workflow for resumable multi-model and multi-judge waves, with explicit partition, dependency, deduplication, and recovery controls."
    },
    "chips": [
      "Slurm",
      "CPU-only evaluation",
      "HUMANUAL",
      "SimulatorArena",
      "Smoke validation",
      "Resumable jobs",
      "Dependency chains",
      "Multi-partition scheduling",
      "Duplicate prevention"
    ],
    "people": [
      {
        "id": "evaluation-lead",
        "releaseLabel": "Evaluation lead",
        "role": "Project requester and execution coordinator",
        "description": "Directed the expansion of model coverage and requested broader, safely coordinated CPU-partition access while preserving active work.",
