    "chapter": {
      "kind": "foundation",
      "title": "From a Lean Runner to Role-Separated Evaluation",
      "overview": "A lightweight evaluator replaced a training-heavy entry path, then matured through dependency failures, provider restrictions, scheduler constraints, and a correction to model-role routing. Fixed auxiliary roles and targeted preflights produced a reusable evaluation foundation, while provider-blocked model routes remained an explicit boundary rather than being mistaken for evaluator failures.",
      "transition": {
        "before": "The first lean runner used the evaluated target model across simulator, assistant, document-generation, and judging paths.",
        "after": "Target and auxiliary roles were independently configured, routed, and verified before controlled reruns."
