          "releaseLabel": "Evaluation agent",
          "role": "Protocol investigator and implementer",
          "description": "Inspected the local and upstream data, traced active model calls and scoring paths, corrected provenance claims, and tested the resulting comparison protocol.",
          "localIdentityState": "local_only",
          "evidence": [
            {
              "documentId": "traj-zxiong-codex-69088da72373fb09",
              "eventId": "evt-9352800c684385235d932fc52de59657fedcd5f82b6496cd17981d6083122127"
            },
            {
              "documentId": "traj-zxiong-codex-69088da72373fb09",
