[
  {
    "ownerId": "chapter-user-specificity-audit",
    "chapter": {
      "kind": "validation",
      "title": "A Direct Audit of User Specificity and Human Indistinguishability",
      "overview": "A direct behavioral audit was designed to test whether existing evaluators recover user-specific and human-like behavior, without treating the audit itself as ground truth. Anonymous comparisons, canonical order correction, leakage controls, common-support analysis, and independent judges produced a bounded result: simulators often matched the real response's profile association, but remained readily distinguishable from real users, while evaluator agreement stayed weak and coarse.",
      "transition": {
        "before": "Existing structured evaluators supplied stable scores, but it was unclear whether those scores tracked target-user specificity or behavior that was difficult to distinguish from a real user.",
        "after": "A reproducible direct-audit protocol separated specificity from source indistinguishability, quantified their agreement with proxy evaluators, and documented the limits created by missing judgments, directional information loss, discrete scores, and profile leakage."
      },
      "chips": [
        "User specificity",
        "Human indistinguishability",
        "Direct audit",
        "Anonymous judgments",
        "Order correction",
        "Leakage controls",
        "Common support",
        "Kendall tau-b",
        "Bootstrap uncertainty",
        "Over-personalization"
      ],
      "people": [
        {
          "id": "evaluation-researcher",
          "releaseLabel": "Evaluation researcher",
          "role": "Audit requester and interpretation reviewer",
          "description": "Requested separate specificity and source analyses, challenged metric wording and order handling, and asked for judge-specific rather than prematurely aggregated reporting.",
          "localIdentityState": "not_identified",
          "evidence": [
            {
              "documentId": "traj-zxiong-codex-19fd7078bb29d827",
              "eventId": "evt-dfd54097cf0339f919ca7db15bd6009eac59d8dabe88e4556832d1bde54f45aa",
              "label": "Request to clarify the meaning of user specificity"
            },
