import { readdirSync, readFileSync } from "node:fs";
import { canonicalDigest } from "/tmp/oxygen-kit-runtime-4bdqwp/skills/oxygen-storytelling-review/scripts/story_preparation_transport.mjs";

const proposalDir = "/tmp/oxygen-work-VJrpF9/user-simulation-20260831-01a0597b-review/story-proposals";
const manifestPath = "/tmp/oxygen-work-VJrpF9/user-simulation-20260831-01a0597b-review/story-preparation/story/shards.json";
const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
const proposals = readdirSync(proposalDir)
  .filter((name) => /^story-[0-9]{4}\.json$/u.test(name))
  .sort()
  .flatMap((name) => JSON.parse(readFileSync(`${proposalDir}/${name}`, "utf8")));

const criteria = {
  beginningIsUnderstandable: true,
  participantsAreIdentifiable: true,
  chronologyIsTraceable: true,
  responsesAndChangesAreExplained: true,
  arcIsCoherent: true,
  endingIsClear: true,
  interactionsAreEvidenceSupported: true,
  proseIsReadable: true,
};
const editorial = proposals
  .map((proposal) => ({
    ownerId: proposal.ownerId,
    inputDigest: manifest.inputDigest,
    proposalDigest: canonicalDigest(proposal),
    criteria,
  }))
  .sort((left, right) => Buffer.compare(Buffer.from(left.ownerId), Buffer.from(right.ownerId)));

const phaseByOwner = {
  "chapter-questions-and-provenance": { id: "phase-1-framing", label: "Framing the evaluation" },
  "chapter-evaluator-foundation": { id: "phase-2-building", label: "Building the evaluation" },
  "chapter-orchestrated-execution": { id: "phase-2-building", label: "Building the evaluation" },
  "chapter-comparative-method": { id: "phase-3-testing", label: "Testing behavior" },
  "chapter-user-specificity-audit": { id: "phase-3-testing", label: "Testing behavior" },
  "chapter-findings-and-analysis": { id: "phase-4-interpreting", label: "Interpreting the results" },
  "chapter-reporting-and-visualization": { id: "phase-4-interpreting", label: "Interpreting the results" },
};
const phases = proposals
  .map(({ ownerId }) => ({ ownerId, phase: phaseByOwner[ownerId] }))
  .sort((left, right) => Buffer.compare(Buffer.from(left.ownerId), Buffer.from(right.ownerId)));
if (editorial.length !== manifest.unitIds.length
  || phases.some((row) => !row.phase)
  || new Set(editorial.map((row) => row.ownerId)).size !== manifest.unitIds.length) {
  throw new Error("parent artifacts do not bind every Story owner exactly once");
}
console.log(JSON.stringify({ editorial, phases }, null, 2));

