  cmd: "node /tmp/emit_story_parent_artifacts.mjs",
  workdir: "/tmp/oxygen-kit-runtime-4bdqwp",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
if (r.exit_code !== 0) { text(r.output); exit(); }
const value = JSON.parse(r.output);
const targets = [
  ["/tmp/oxygen-work-VJrpF9/user-simulation-20260831-01a0597b-review/story-editorial-review.json", value.editorial],
  ["/tmp/oxygen-work-VJrpF9/user-simulation-20260831-01a0597b-review/story-phases.json", value.phases]
];
for (const [path, obj] of targets) {
  const content = JSON.stringify(obj, null, 2);
  const lines = content.split("\n").map(line=>`+${line}`).join("\n");
  await tools.apply_patch(`*** Begin Patch\n*** Add File: ${path}\n${lines}\n*** End Patch`);
}
text(JSON.stringify({editorialRows:value.editorial.length, phaseRows:value.phases.length, proposalDigests:value.editorial.map(x=>[x.ownerId,x.proposalDigest])},null,2));

