          canonicalAuthorityJson(unit) !== canonicalAuthorityJson(semanticById.get(unit.id))
          || coverageById.get(unit.id)?.disposition !== "represented"
          || coverageById.get(unit.id)?.ownerId !== bundle.ownerId
        ))) fail("WORKER_INPUT_TAMPERED");
