      if (leftPart < rightPart) return -1;
      if (leftPart > rightPart) return 1;
    } else if (typeof leftPart === "string" && typeof rightPart === "string") {
      if (leftPart < rightPart) return -1;
      if (leftPart > rightPart) return 1;
    }
  }
  return 0;
}

