    || /^tool(?:_|$)/u.test(eventType) || eventType.endsWith("_action")
    || eventType.endsWith(" action")) return "";
  return String(row.actorEquivalence || "").trim();
}

const changed = [];
for (const name of readdirSync(`${root}/story-proposals`).sort()) {
  const path = `${root}/story-proposals/${name}`;
  const proposal = JSON.parse(readFileSync(path, "utf8"));
