  if (valid && [...groups.keys()].every((actor) => covered.has(actor))) continue;

  const beforeWithoutPeople = { ...chapter };
  delete beforeWithoutPeople.people;
  let contributorIndex = 0;
  let agentIndex = 0;
  chapter.people = [...groups.values()].map((group, index) => {
    const isContributor = String(group.actorType || "").toLowerCase() === "user";
    if (isContributor) contributorIndex += 1;
    else agentIndex += 1;
    const ordinal = isContributor ? contributorIndex : agentIndex;
    return {
      id: `participant-${String(index + 1).padStart(2, "0")}`,
      releaseLabel: isContributor ? `Project contributor ${ordinal}` : `Evaluation agent ${ordinal}`,
      role: isContributor ? "Evaluation direction and review" : "Research, implementation, and analysis",
      description: isContributor
        ? "Set or refined the request, constraints, or interpretation documented in this chapter."
        : "Produced the implementation, investigation, execution, or analysis documented in this chapter.",
      localIdentityState: "not_identified",
      evidence: group.references,
    };
  });
  const afterWithoutPeople = { ...chapter };
  delete afterWithoutPeople.people;
  if (digest(beforeWithoutPeople) !== digest(afterWithoutPeople)) {
    throw new Error(`non-People Story content changed for ${name}`);
  }
  writeFileSync(path, `${JSON.stringify(proposal, null, 2)}\n`, "utf8");
  changed.push({ name, ownerId: proposal[0].ownerId, people: chapter.people.length });
}
console.log(JSON.stringify({ changed }, null, 2));

