  cmd: "node /tmp/emit_story_parent_artifacts.mjs",
  workdir: "/tmp/oxygen-kit-runtime-4bdqwp",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
const current = JSON.parse(currentResult.output.slice(currentResult.output.indexOf("[")));
const emitted = JSON.parse(emittedResult.output.slice(emittedResult.output.indexOf("{"))).editorial;
const changes = [];
for (const next of emitted) {
  const prior = current.find(x=>x.ownerId===next.ownerId);
  if (prior.proposalDigest !== next.proposalDigest) {
    await tools.apply_patch(`*** Begin Patch\n*** Update File: /tmp/oxygen-work-VJrpF9/user-simulation-20260831-01a0597b-review/story-editorial-review.json\n@@\n-    \"proposalDigest\": \"${prior.proposalDigest}\",\n+    \"proposalDigest\": \"${next.proposalDigest}\",\n*** End Patch`);
    changes.push([next.ownerId,next.proposalDigest]);
  }
}
